import { useEffect, useRef, useState, useCallback } from 'react';
import gsap from 'gsap';
import { useCursorZone } from '@/hooks/useCursorZone';

type CursorState = 'default' | 'interactive' | 'grab' | 'text' | 'magnetic';

interface MagneticTarget {
  el: HTMLElement;
  rect: DOMRect;
  label: string;
}

export default function CustomCursor() {
  const ringRef = useRef<HTMLDivElement>(null);
  const dotRef  = useRef<HTMLDivElement>(null);
  const zone    = useCursorZone();

  const [state, setState]     = useState<CursorState>('default');
  const [label, setLabel]     = useState('');
  const [isTouch, setIsTouch] = useState(false);
  const [clicking, setClicking] = useState(false);
  const [isVisible, setIsVisible] = useState(false);

  // GSAP quickTo refs — ring (laggy) and dot (instant)
  const ringX = useRef<ReturnType<typeof gsap.quickTo> | null>(null);
  const ringY = useRef<ReturnType<typeof gsap.quickTo> | null>(null);
  const dotX  = useRef<ReturnType<typeof gsap.quickTo> | null>(null);
  const dotY  = useRef<ReturnType<typeof gsap.quickTo> | null>(null);

  // Magnetic state
  const magnetRef    = useRef<MagneticTarget | null>(null);
  const magnetActive = useRef(false);
  const pointerRef = useRef({ x: 0, y: 0, hasPosition: false });

  const applyCursorPosition = useCallback((clientX: number, clientY: number) => {
    if (magnetActive.current && magnetRef.current) {
      const { rect } = magnetRef.current;
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      const dx = (clientX - cx) * 0.35;
      const dy = (clientY - cy) * 0.35;
      dotX.current?.(cx + dx);
      dotY.current?.(cy + dy);
      ringX.current?.(cx + dx * 0.5);
      ringY.current?.(cy + dy * 0.5);
      return;
    }

    dotX.current?.(clientX);
    dotY.current?.(clientY);
    ringX.current?.(clientX);
    ringY.current?.(clientY);
  }, []);

  const resetCursorState = useCallback(() => {
    magnetActive.current = false;
    magnetRef.current = null;
    setState('default');
    setLabel('');
    setClicking(false);
  }, []);

  // ─── Touch detection ───────────────────────────────────────────
  useEffect(() => {
    setIsTouch(window.matchMedia('(pointer: coarse)').matches);
  }, []);

  // ─── Init GSAP quickTo ─────────────────────────────────────────
  useEffect(() => {
    if (!ringRef.current || !dotRef.current) return;
    gsap.set(ringRef.current, { xPercent: -50, yPercent: -50 });
    gsap.set(dotRef.current, { xPercent: -50, yPercent: -50 });
    // Ring: slower, lagging follow — creates the trailing illusion
    ringX.current = gsap.quickTo(ringRef.current, 'x', { duration: 0.12, ease: 'power3.out' });
    ringY.current = gsap.quickTo(ringRef.current, 'y', { duration: 0.12, ease: 'power3.out' });
    // Dot: near-instant
    dotX.current  = gsap.quickTo(dotRef.current,  'x', { duration: 0.01, ease: 'none' });
    dotY.current  = gsap.quickTo(dotRef.current,  'y', { duration: 0.01, ease: 'none' });
  }, []);

  // ─── Mouse tracking ────────────────────────────────────────────
  useEffect(() => {
    if (isTouch) return;
    const onMove = (e: PointerEvent) => {
      if (e.pointerType && e.pointerType !== 'mouse') return;
      setIsVisible(true);
      const mx = e.clientX;
      const my = e.clientY;
      pointerRef.current = { x: mx, y: my, hasPosition: true };
      applyCursorPosition(mx, my);
    };

    const hideCursor = () => {
      pointerRef.current.hasPosition = false;
      setIsVisible(false);
      resetCursorState();
    };

    window.addEventListener('pointermove', onMove, { passive: true });
    window.addEventListener('blur', hideCursor);
    document.addEventListener('visibilitychange', hideCursor);
    document.documentElement.addEventListener('mouseleave', hideCursor);

    return () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('blur', hideCursor);
      document.removeEventListener('visibilitychange', hideCursor);
      document.documentElement.removeEventListener('mouseleave', hideCursor);
    };
  }, [applyCursorPosition, isTouch, resetCursorState]);

  // ─── Click pulse ───────────────────────────────────────────────
  useEffect(() => {
    if (isTouch) return;
    const onDown = () => setClicking(true);
    const onUp   = () => setTimeout(() => setClicking(false), 320);
    window.addEventListener('mousedown', onDown);
    window.addEventListener('mouseup',   onUp);
    return () => {
      window.removeEventListener('mousedown', onDown);
      window.removeEventListener('mouseup',   onUp);
    };
  }, [isTouch]);

  // ─── Hover detection ───────────────────────────────────────────
  const detectState = useCallback((target: HTMLElement): CursorState => {
    if (!target) return 'default';
    if (target.tagName === 'CANVAS' || target.closest('[data-cursor="grab"]')) return 'grab';

    const mag = target.closest('[data-cursor="magnetic"]') as HTMLElement | null;
    if (mag) {
      magnetActive.current = true;
      const lbl = mag.dataset.cursorLabel ?? '';
      setLabel(lbl);
      magnetRef.current = { el: mag, rect: mag.getBoundingClientRect(), label: lbl };
      return 'magnetic';
    }

    if (
      target.tagName === 'P'        ||
      target.tagName === 'TEXTAREA' ||
      target.tagName === 'INPUT'    ||
      target.closest('[data-cursor="text"]')
    ) return 'text';

    if (
      target.tagName === 'A'   || target.tagName === 'BUTTON' ||
      target.closest('a')      || target.closest('button')    ||
      target.closest('[data-cursor="pointer"]')
    ) return 'interactive';

    return 'default';
  }, []);

  useEffect(() => {
    if (isTouch) return;
    const onOver = (e: PointerEvent) => {
      if (e.pointerType && e.pointerType !== 'mouse') return;
      const next = detectState(e.target as HTMLElement);
      if (next !== 'magnetic') {
        magnetActive.current = false;
        magnetRef.current    = null;
        setLabel('');
      }
      setState(next);
    };

    const onOut = (e: PointerEvent) => {
      if (e.pointerType && e.pointerType !== 'mouse') return;
      if (e.relatedTarget) return;
      setIsVisible(false);
      resetCursorState();
    };

    window.addEventListener('pointerover', onOver, { passive: true });
    window.addEventListener('pointerout', onOut, { passive: true });
    return () => {
      window.removeEventListener('pointerover', onOver);
      window.removeEventListener('pointerout', onOut);
    };
  }, [isTouch, detectState, resetCursorState]);

  // ─── Re-measure magnetic rect on scroll/resize ─────────────────
  useEffect(() => {
    if (isTouch) return;
    const refresh = () => {
      const pointer = pointerRef.current;
      if (!pointer.hasPosition) return;

      const target = document.elementFromPoint(pointer.x, pointer.y) as HTMLElement | null;
      if (target) {
        const next = detectState(target);
        setState(next);
        if (next !== 'magnetic') {
          magnetActive.current = false;
          magnetRef.current = null;
          setLabel('');
        }
      } else {
        resetCursorState();
      }

      if (magnetRef.current) {
        magnetRef.current.rect = magnetRef.current.el.getBoundingClientRect();
      }

      applyCursorPosition(pointer.x, pointer.y);
    };
    window.addEventListener('scroll', refresh, { passive: true });
    window.addEventListener('resize', refresh);
    return () => {
      window.removeEventListener('scroll', refresh);
      window.removeEventListener('resize', refresh);
    };
  }, [applyCursorPosition, detectState, isTouch, resetCursorState]);

  if (isTouch) return null;

  const zoneClass = zone === 'dark' ? 'dark' : 'light';

  const ringClasses = [
    'cursor-ring',
    `cursor-ring--${zoneClass}`,
    state !== 'default' ? `cursor-ring--${state}` : '',
    clicking            ? 'cursor-ring--clicking'  : '',
    !isVisible          ? 'cursor-ring--hidden'    : '',
  ].filter(Boolean).join(' ');

  const dotClasses = [
    'cursor-dot',
    `cursor-dot--${zoneClass}`,
    state !== 'default' ? `cursor-dot--${state}` : '',
    !isVisible          ? 'cursor-dot--hidden'   : '',
  ].filter(Boolean).join(' ');

  return (
    <>
      {/* Outer ring — lagging follow */}
      <div ref={ringRef} className={ringClasses} aria-hidden="true">
        {state === 'grab' && (
          <div className="cursor-rotate-icon">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.2">
              <path d="M1 4v6h6M23 20v-6h-6" />
              <path d="M20.49 9A9 9 0 0 0 5.64 5.64L1 10m22 4l-4.64 4.36A9 9 0 0 1 3.51 15" />
            </svg>
          </div>
        )}
        {state === 'magnetic' && label && (
          <div className="cursor-label">{label}</div>
        )}
      </div>
      {/* Inner dot — instant follow */}
      <div ref={dotRef} className={dotClasses} aria-hidden="true" />
    </>
  );
}
