import { useEffect, useState, useRef } from 'react';

type Zone = 'dark' | 'light';

/**
 * Reports whether the cursor is currently over a dark or light zone.
 * Uses data-cursor-zone="dark"|"light" attributes on section elements.
 * Falls back to 'dark' if no zone is detected.
 */
export function useCursorZone(): Zone {
  const [zone, setZone] = useState<Zone>('dark');
  const rafRef = useRef<number>(0);
  const pointerRef = useRef({ x: 0, y: 0, hasPosition: false });

  useEffect(() => {
    const updateZone = (clientX: number, clientY: number) => {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = requestAnimationFrame(() => {
        // Get the topmost element under the cursor and walk up its ancestors
        const top = document.elementFromPoint(clientX, clientY) as HTMLElement | null;
        if (top) {
          const zoneEl = top.closest<HTMLElement>('[data-cursor-zone]');
          if (zoneEl) {
            const val = zoneEl.dataset.cursorZone;
            if (val === 'dark' || val === 'light') {
              setZone(val);
              return;
            }
          }
        }
        setZone('dark');
      });
    };

    const handlePointerMove = (e: PointerEvent) => {
      if (e.pointerType && e.pointerType !== 'mouse') return;
      pointerRef.current = { x: e.clientX, y: e.clientY, hasPosition: true };
      updateZone(e.clientX, e.clientY);
    };

    const handleViewportChange = () => {
      if (!pointerRef.current.hasPosition) return;
      updateZone(pointerRef.current.x, pointerRef.current.y);
    };

    window.addEventListener('pointermove', handlePointerMove, { passive: true });
    window.addEventListener('scroll', handleViewportChange, { passive: true });
    window.addEventListener('resize', handleViewportChange);
    return () => {
      window.removeEventListener('pointermove', handlePointerMove);
      window.removeEventListener('scroll', handleViewportChange);
      window.removeEventListener('resize', handleViewportChange);
      cancelAnimationFrame(rafRef.current);
    };
  }, []);

  return zone;
}
